                            class Solution {
    // Function to print a square pattern of stars
    pattern1(N) {
        // Outer loop to handle rows
        for (let i = 0; i < N; i++) {
            let row = ""; // Initialize an empty string for the row
            // Inner loop to handle columns for each row
            for (let j = 0; j < N; j++) {
                // Add a star followed by a space to the row string
                row += "* "; 
            }
            // Print the complete row
            console.log(row); 
        }
    }
}

// Driver code
const sol = new Solution();
const N = 5; // Set the size of the square (5x5)
sol.pattern1(N); // Call the function to print the pattern







                            Complexity Analysis




                    Time Complexity: O(N²), since we print N stars for each of the N rows.
                    Space Complexity: O(1), no additional space is used apart from loop variables.

Algorithm





                            This is one of the simplest star patterns.
                            We need to form a right-angled triangle where the number of stars in each row increases line
                            by line.
                            Row i contains exactly i + 1 stars.




                            Run an outer loop from 0 to N-1 to handle rows.
                            For each row i, run an inner loop from 0 to i.

                            In the inner loop, print a star (*).
                            After finishing the stars of one row, move to the next line using endl.






                        Code






                        CppJavaPythonJavascript








                                1234567891011121314151617181920212223242526272829

                            #include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    // Function to print Pattern 2
    void pattern2(int N) {
        // Loop for rows
        for (int i = 0; i < N; i++) {
            // Loop for columns (stars in each row)
            for (int j = 0; j <= i; j++) {
                cout << "* ";
            }
            // Move to next line after each row
            cout << endl;
        }
    }
};

int main() {
    // Create solution object
    Solution sol;
    // Define N
    int N = 5;
    // Call pattern function
    sol.pattern2(N);
    return 0;
}




