Approach.description:
Algorithm



                        Intuition: This pattern prints alternating 1s and 0s in each row, starting
                            with 1 on even-indexed rows and 0 on odd-indexed rows. The value alternates after each print
                            using basic toggling logic.


                            Take an integer N as input representing the number of rows.
                            Loop from 0 to N-1 to handle each row.
                            If the row index is even, set the starting value to 1; otherwise, set it to 0.
                            For each row, print i+1 numbers while toggling the value between 1 and 0 after each
                                print.
                            After printing each row, move to the next line.





                        Code






                        CppJavaPythonJavascript








                                12345678910111213141516171819202122232425262728293031323334

                            #include <bits/stdc++.h>
using namespace std;

void pattern11(int N) {
    // First row starts by printing a single 1.
    int start = 1;

    // Outer loop for the number of rows
    for (int i = 0; i < N; i++) {
        // If the row index is even, print 1 first in that row
        if (i % 2 == 0) start = 1;

        // If the row index is odd, print 0 first in that row
        else start = 0;

        // Inner loop to print alternating 1's and 0's in each row
        for (int j = 0; j <= i; j++) {
            cout << start;
            // Alternate between 1 and 0
            start = 1 - start;
        }

        // Move to the next line after each row is printed
        cout << endl;
    }
}

int main() {
    // The size of the square pattern is N
    int N = 5;
    pattern11(N); // Print the pattern
    return 0;
}




