Approach.description:
Algorithm



                        Intuition: This pattern prints a mirrored sequence of numbers on both sides
                            with spaces in the center. The outer digits increase and decrease symmetrically, while the
                            center gap shrinks with each row, forming a diamond-like structure across rows.


                            Initialize the number of spaces between the two number sequences as 2 × (N - 1).
                            Loop from 1 to N to handle each row.
                            Print increasing numbers from 1 to i on the left side of the row.
                            Print the current number of spaces in the middle.
                            Print decreasing numbers from i to 1 on the right side of the row.
                            Move to the next line after completing the row.
                            Reduce the number of middle spaces by 2 after each row.






                        Code






                        CppJavaPythonJavascript








                                123456789101112131415161718192021222324252627282930313233343536373839404142

                            #include <bits/stdc++.h>
using namespace std;

// Function to print the pattern
void pattern12(int N) {
    // Initial number of spaces in the first row
    int spaces = 2 * (N - 1);

    // Outer loop for the number of rows
    for (int i = 1; i <= N; i++) {

        // Inner loop to print numbers in increasing order
        for (int j = 1; j <= i; j++) {
            cout << j;
        }

        // Inner loop to print spaces in the middle
        for (int j = 1; j <= spaces; j++) {
            cout << " ";
        }

        // Inner loop to print numbers in decreasing order
        for (int j = i; j >= 1; j--) {
            cout << j;
        }

        // Move to the next line after printing the row
        cout << endl;

        // Decrease spaces by 2 after each row
        spaces -= 2;
    }
}

int main() {
    // Set the value of N
    int N = 5;
    pattern12(N); // Call the function to print the pattern

    return 0;
}




