Approach.description:
Algorithm





                            The pattern consists of two mirrored halves forming an hourglass-like shape made of stars
                            (*).
                            The upper half starts with N stars on both sides and gradually reduces, while
                            the lower half starts with 1 star on both sides and gradually increases.
                            Spaces in between adjust accordingly to maintain symmetry.




                            Upper Half:

                                    Initialize iniS = 0 (number of spaces between the two star blocks).

                                    For each row i from 0 to N-1:

                                            Print N - i stars.
                                            Print iniS spaces.
                                            Print N - i stars again.
                                            Increase iniS by 2.




                            Lower Half:

                                    Initialize iniS = 2 * N - 2.
                                    For each row i from 1 to N:

                                            Print i stars.
                                            Print iniS spaces.
                                            Print i stars again.
                                            Decrease iniS by 2.









                        Code








                    C++JavaPythonJavaScript



                                1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859606162636465

                            #include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    // Function to print Pattern 19
    void pattern19(int N) {
        // Initial spaces for upper half
        int iniS = 0;

        // Loop for upper half rows
        for (int i = 0; i < N; i++) {
            // Print stars on left
            for (int j = 1; j <= N - i; j++) {
                cout << "*";
            }
            // Print spaces in middle
            for (int j = 0; j < iniS; j++) {
                cout << " ";
            }
            // Print stars on right
            for (int j = 1; j <= N - i; j++) {
                cout << "*";
            }
            // Increase middle spaces by 2
            iniS += 2;
            // Move to next row
            cout << endl;
        }

        // Initial spaces for lower half
        iniS = 2 * N - 2;

        // Loop for lower half rows
        for (int i = 1; i <= N; i++) {
            // Print stars on left
            for (int j = 1; j <= i; j++) {
                cout << "*";
            }
            // Print spaces in middle
            for (int j = 0; j < iniS; j++) {
                cout << " ";
            }
            // Print stars on right
            for (int j = 1; j <= i; j++) {
                cout << "*";
            }
            // Decrease middle spaces by 2
            iniS -= 2;
            // Move to next row
            cout << endl;
        }
    }
};

int main() {
    // Create solution object
    Solution sol;
    // Define N
    int N = 5;
    // Call pattern function
    sol.pattern19(N);
    return 0;
}




