Approach.description:
Algorithm





                            We need to print a square of size n × n but only with stars on the border,
                            leaving the inner cells as spaces.
                            This creates a "hollow square" effect.




                            Run an outer loop i from 0 to n-1 (rows).
                            Inside, run an inner loop j from 0 to n-1
                                (columns).
                            For each position (i, j):

                                    If it lies on the border (i == 0, j == 0,
                                        i == n-1, j == n-1), print *.

                                    Else, print a space.


                            After printing one row, move to the next line.





                        Code








                    C++JavaPythonJavaScript



                                12345678910111213141516171819202122232425262728293031323334

                            #include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    // Function to print hollow square pattern
    void pattern21(int n) {
        // Outer loop for rows
        for (int i = 0; i < n; i++) {
            // Inner loop for columns
            for (int j = 0; j < n; j++) {
                // Print star if it's a border cell
                if (i == 0 || j == 0 || i == n - 1 || j == n - 1)
                    cout << "*";
                // Print space otherwise
                else
                    cout << " ";
            }
            // Move to next line after each row
            cout << endl;
        }
    }
};

int main() {
    // Create solution object
    Solution sol;
    // Define N
    int N = 5;
    // Call pattern function
    sol.pattern21(N);
    return 0;
}




