Approach.description:
Algorithm





                            We need to print a square matrix of size (2 * n - 1) × (2 * n - 1).
                            The outermost border should contain n, the next inner layer n-1,
                            then n-2, and so on until the center which contains 1.
                            This creates a concentric square pattern.




                            We use two nested loops:

                                    Outer loop runs for rows (i from 0 to
                                        2n-2).
                                    Inner loop runs for columns (j from 0 to
                                        2n-2).


                            For each cell (i, j), compute its distance from all four borders:

                                    top = i
                                    left = (2n - 2) - i
                                    bottom = j
                                    right = (2n - 2) - j


                            Take the minimum of these four distances.
                                This tells us how deep we are inside the square.
                            Print n - minDistance at that position.





                        Code






                        CppJavaPythonJavascript








                                123456789101112131415161718192021222324252627282930313233343536373839404142434445

                            #include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    // Function to print concentric square number pattern
    void pattern22(int n) {
        // Outer loop for rows
        for (int i = 0; i < 2 * n - 1; i++) {
            // Inner loop for columns
            for (int j = 0; j < 2 * n - 1; j++) {
                // Calculate distance from top
                int top = i;
                // Calculate distance from left
                int left = j;
                // Calculate distance from bottom
                int bottom = (2 * n - 2) - i;
                // Calculate distance from right
                int right = (2 * n - 2) - j;

                // Take the minimum of all four distances
                int minDist = min(min(top, bottom), min(left, right));

                // Print number (starts with n at border, decreases inside)
                cout << (n - minDist) << " ";
            }
            // Move to the next row
            cout << endl;
        }
    }
};

int main() {
    // Create object of Solution class
    Solution sol;

    // Define size of pattern
    int N = 5;

    // Call pattern function
    sol.pattern22(N);

    return 0;
}




