                let bottom = (2 * n - 2) - i;
                // Calculate distance from right
                let right = (2 * n - 2) - j;

                // Take the minimum of all four distances
                let minDist = Math.min(top, bottom, left, right);

                // Append number (starts with n at border, decreases inside)
                row += (n - minDist) + " ";
            }
            // Print row
            console.log(row);
        }
    }
}

