Brute Force Approach.description:
Algorithm





                            To check whether a string is a palindrome, we only need to compare characters from the
                                start and end, moving towards the center.
                            Run a for loop from i = 0 to
                                i < str.length() / 2. This ensures that each character is compared with
                                its corresponding character from the end.

                            In each iteration, compare the character at the front str[i] with the
                                character at the back str[str.length() - i - 1].
                            If at any point these characters do not match, return false as the string
                                is not a palindrome.
                            If the loop completes without returning false, then the string is a
                                palindrome, and we return true.





                        Code








                    C++JavaPythonJavaScript



                                1234567891011121314151617181920212223242526272829303132333435363738394041

                            #include <bits/stdc++.h>
using namespace std;

// Function to check if a string is a palindrome
bool isPalindrome(string s) {
    int left = 0, right = s.length() - 1;

    // Loop to check if the string is a palindrome
    while (left < right) {
        // Skip non-alphanumeric characters on the left side
        if (!isalnum(s[left])) 
            left++;
        // Skip non-alphanumeric characters on the right side
        else if (!isalnum(s[right])) 
            right--;
        // If characters are different, it's not a palindrome
        else if (tolower(s[left]) != tolower(s[right])) 
            return false;
        else {
            // Move towards the middle if characters are the same
            left++; 
            right--;
        }
    }
    return true;  // The string is a palindrome if the loop completes
}

int main() {
    string str = "ABCDCBA";  // String to check for palindrome
    bool ans = isPalindrome(str);  // Check if the string is a palindrome

    // Output the result
    if (ans == true) {
        cout << "Palindrome";
    } else {
        cout << "Not Palindrome";
    }

    return 0;
}




