Optimal Approach.description:
Algorithm






                            Use recursion to compare characters at the start and end of the string.
                            If the characters are not equal, return false indicating the string is not a palindrome.

                            If they are equal, recursively call the function with the next set of indices: start + 1
                                and end - 1.
                            Base Case: If the start index becomes greater than or equal to the end index, return
                                true as it means the entire string has been checked and is a palindrome.






                        Code








                    C++JavaPythonJavaScript



                                1234567891011121314151617181920212223242526

                            #include<bits/stdc++.h>
using namespace std;

// Function to check if a string is a palindrome using recursion
bool palindrome(int i, string& s) {
    // Base Condition: If i exceeds half of the string, all the elements have been compared
    // and the string is a palindrome, return true.
    if (i >= s.length() / 2) return true;

    // If the start and end characters are not equal, it's not a palindrome.
    if (s[i] != s[s.length() - i - 1]) return false;

    // If both characters are the same, increment i and check start+1 and end-1.
    return palindrome(i + 1, s);
}

int main() {
    // Example string.
    string s = "madam";

    // Check if the string is a palindrome and output the result
    cout << palindrome(0, s);  // Output 1 if palindrome, 0 if not
    cout << endl;
    return 0;
}




