    C++JavaPythonJavaScript123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051#include<bits/stdc++.h>
using namespace std;

class Solution {
public:
    //Function to find the leaders in an array.
    vector<int> leaders(vector<int>& nums) {
        vector<int> ans;

        if(nums.empty()) {
            return ans;
        }

        // Last element of the vector is always a leader
        int max = nums[nums.size() - 1];
        ans.push_back(nums[nums.size() - 1]);

        // Check elements from right to left
        for (int i = nums.size() - 2; i >= 0; i--) {
            if (nums[i] > max) {
                ans.push_back(nums[i]);
                max = nums[i];
            }
        }

        /* Reverse the vector to match
        the required output order*/
        reverse(ans.begin(), ans.end());

        //Return the leaders
        return ans;
    }
};

