            if (i > 0 && arr[i] === arr[i - 1]) continue;

            // Two pointers
            let left = i + 1, right = n - 1;

            // Find pairs for current arr[i]
            while (left < right) {
                let sum = arr[i] + arr[left] + arr[right];

                if (sum === 0) {
