Brute-Force Approach.description:
Algorithm







     We to find the total number of subarrays (continuous segments of the array) such that the XOR of all elements in that subarray equals B.

A brute force way would be to consider every possible subarray of the array and check its XOR.

 Initialize a counter to 0 for storing the number of valid subarrays. Loop through each index i as the starting point of the subarray. Set a variable xor = 0 for maintaining the running XOR of the current subarray. Loop through each index j from i to n-1 to extend the subarray. Update xor by taking xor = xor ^ A[j]. If xor equals B, increment the counter by 1. After all iterations, return the counter as the total number of subarrays. 




        Code



    C++JavaPythonJavaScript12345678910111213141516171819202122232425262728293031323334353637#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    // Function to count subarrays with XOR equal to B
    int countSubarraysXOR(vector<int>& A, int B) {
        // Initialize count of valid subarrays
        int count = 0;
        // Traverse all starting points
        for (int i = 0; i < A.size(); i++) {
            // Maintain xor of current subarray
            int xorVal = 0;
            // Extend subarray till end
            for (int j = i; j < A.size(); j++) {
                // Update xor
                xorVal ^= A[j];
                // If xor equals B, increment count
                if (xorVal == B) {
                    count++;
                }
            }
        }
        return count;
    }
};

int main() {
    // Input array
    vector<int> A = {4, 2, 2, 6, 4};
    // Target xor
    int B = 6;

    Solution sol;
    cout << sol.countSubarraysXOR(A, B) << endl;
    return 0;
}
