Brute Force Approach.description:
Algorithm





                                    An inversion in an array is defined as a pair of indices (i, j) such
                                    that
                                    i < j and a[i] > a[j].
                                    This measures how far the array is from being sorted.
                                    To count inversions, the brute force way is to compare every element with all
                                    elements to its right
                                    and increment the counter whenever we find an inversion.




                                    Initialize a counter cnt = 0.
                                    Use two nested loops:

                                            Outer loop runs for each element a[i].
                                            Inner loop checks all elements a[j] where
                                                j > i.

                                            If a[i] > a[j], increment cnt.


                                    After traversing all pairs, return cnt as the number of inversions.






                                Code








                            C++JavaPythonJavaScript



                                        123456789101112131415161718192021222324

                                    #include <bits/stdc++.h>
using namespace std;

// Function to count the number of inversions in an array
// An inversion is a pair (i, j) such that i < j and arr[i] > arr[j]
int numberOfInversions(vector<int>& a, int n) {
    int cnt = 0; // Initialize inversion count
    // Check all pairs
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (a[i] > a[j]) cnt++; // Increment count if inversion found
        }
    }
    return cnt; // Return total inversions
}

int main() {
    vector<int> a = {5, 4, 3, 2, 1};
    int n = a.size();
    int cnt = numberOfInversions(a, n);
    cout << "The number of inversions is: " << cnt << endl;
    return 0;
}




