Brute Force Approach.description:
Algorithm








The brute force way is to simply check each element from left to right. If we find the target, we return its index; otherwise, we return -1 after scanning the entire array.

 Start a loop from the first element to the last element. For each element:  Compare it with the target value. If it matches the target, return the current index immediately.   If the loop finishes and no match is found, return -1. 
1/3








        Code



    C++JavaPythonJavaScript1234567891011121314151617181920212223242526272829303132333435#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    // Function to search target in rotated sorted array using brute force
    int search(vector<int>& nums, int target) {

        // Loop through each element in the array
        for (int i = 0; i < nums.size(); i++) {

            // If current element matches target, return index
            if (nums[i] == target) {
                return i;
            }
        }

        // If not found, return -1
        return -1;
    }
};

// Driver code
int main() {
    vector<int> nums = {4, 5, 6, 7, 0, 1, 2};
    int target = 0;

    Solution obj;
    int index = obj.search(nums, target);

    cout << index << endl;

