            if (this.canPlace(stalls, cows, mid)) {
                // Store answer
                ans = mid;
                // Try larger distance
                low = mid + 1;
            } else {
                // Try smaller distance
                high = mid - 1;
            }
        }
        // Return result
        return ans;
    }
}

