class MaxHeap {
  constructor() {
    this.heap = [];
  }

  // Insert an element into the heap
  push(value) {
    this.heap.push(value);
    this._heapifyUp();
  }

  // Remove and return the max element (root)
  pop() {
    if (this.heap.length === 0) return null;
    const max = this.heap[0];
    const end = this.heap.pop();
    if (this.heap.length > 0) {
      this.heap[0] = end;
      this._heapifyDown();
    }
    return max;
  }

  // Return the max element without removing
  top() {
    return this.heap[0];
  }

  // Get the number of elements
  size() {
    return this.heap.length;
  }

  // Maintain heap property after insertion
  _heapifyUp() {
    let index = this.heap.length - 1;
    while (
      index > 0 &&
      this.heap[Math.floor((index - 1) / 2)][0] < this.heap[index][0]
    ) {
      const parentIdx = Math.floor((index - 1) / 2);
      [this.heap[parentIdx], this.heap[index]] = [this.heap[index], this.heap[parentIdx]];
      index = parentIdx;
    }
  }

  // Maintain heap property after removal
  _heapifyDown() {
    let index = 0;
    const length = this.heap.length;

    while (true) {
      let left = 2 * index + 1;
      let right = 2 * index + 2;
      let largest = index;

      if (left < length && this.heap[left][0] > this.heap[largest][0]) {
        largest = left;
      }
      if (right < length && this.heap[right][0] > this.heap[largest][0]) {
        largest = right;
      }

      if (largest === index) break;

      [this.heap[index], this.heap[largest]] = [this.heap[largest], this.heap[index]];
      index = largest;
    }
  }
}

