Approach.description:
Algorithm









                        Focus on finding the longest valid odd number starting from the original string.
                        An odd number must end with an odd digit, so we look for the last odd digit when scanning from the end.
                        Leading zeroes don’t add value to the number, so we aim to remove them for a cleaner representation.
                        Once the endpoint (last odd digit) is determined, we identify the starting point by skipping any leading zeroes before it.
                        Extract the portion between these two positions, this gives the largest possible odd integer from the string.





        Code



    CppJavaPythonJavascript


    1234567891011121314151617181920212223242526272829303132333435#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    // Returns the largest odd number substring from the given string
    string largeOddNum(string& s) {
        int ind = -1;

        // Find the last odd digit in the string
        int i;
        for (i = s.length() - 1; i >= 0; i--) {
            if ((s[i] - '0') % 2 == 1) {
                ind = i;
                break;
            }
        }

        // Skip leading zeroes up to the odd digit
        i = 0;
        while (i <= ind && s[i] == '0') i++;

        // Return substring from first non-zero to odd digit
        return s.substr(i, ind - i + 1);
    }
};

int main() {
    Solution solution;
    string num = "504";
    string result = solution.largeOddNum(num);
    cout << "Largest odd number: " << result << endl;
    return 0;
}
