Approach.description:
Algorithm 









                      Loop through all substrings of the string.
                      Maintain a frequency map of characters for each substring.
                      For each substring:
                      Find the most frequent character's count.

                        Find the least frequent non-zero character's count.
                        Calculate the difference between the two counts.
                        Add the difference to the running sum.






        Code



    CppJavaPythonJavascript


    1234567891011121314151617181920212223242526272829303132333435363738394041#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int beautySum(string s) {
        int n = s.length();
        int sum = 0;

        // Loop over all substrings
        for (int i = 0; i < n; i++) {
            unordered_map<char, int> freq;

            for (int j = i; j < n; j++) {
                // Increase frequency of current character
                freq[s[j]]++;

                int maxi = INT_MIN;
                int mini = INT_MAX;

                // Find max and min frequency
                for (auto it : freq) {
                    mini = min(mini, it.second);
                    maxi = max(maxi, it.second);
                }

                // Add difference to sum
                sum += (maxi - mini);
            }
        }

        return sum;
    }
};

int main() {
    Solution sol;
    string s = "xyx";
    cout << "Beauty Sum: " << sol.beautySum(s) << endl;
    return 0;
