Approach.description:
Algorithm








We can solve this using backtracking. Starting from each cell in the grid, we explore all four possible directions (up, down, left, right) to try to match the next character in the word. We mark visited cells temporarily to avoid reusing them, and backtrack when a path fails. This ensures we explore all possible connected sequences of characters in the board that might form the target word.


  Iterate through each cell in the board.
  If the cell matches the first letter of the word, start a DFS search from that cell.
  In DFS, check boundary conditions and whether the character matches the current letter in the word.
  If matched, temporarily mark the cell as visited.
  Recursively search in all four directions for the next letter.
  If the whole word is found, return true.
  Backtrack by restoring the cell’s original value before returning.
  If no path matches the word, return false.


                    1/5







        Code



    C++JavaPythonJavaScript1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859606162636465#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    // Function to check if the word exists in the board
    bool exist(vector<vector<char>>& board, string word) {
        // Get number of rows
        int rows = board.size();
        // Get number of columns
        int cols = board[0].size();

        // Loop through every cell in the grid
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // Start DFS if first letter matches
                if (dfs(board, word, i, j, 0)) {
                    return true;
                }
            }
        }
        // If no path found, return false
        return false;
    }

private:
    // DFS function to search for the word
    bool dfs(vector<vector<char>>& board, string& word, int i, int j, int idx) {
        // If all characters matched, return true
        if (idx == word.size()) return true;

        // Check boundaries and character match
        if (i < 0 || j < 0 || i >= board.size() || j >= board[0].size() || board[i][j] != word[idx]) {
            return false;
        }

        // Store current character and mark as visited
        char temp = board[i][j];
        board[i][j] = '#';

        // Explore all four directions
        bool found = dfs(board, word, i + 1, j, idx + 1) ||
                     dfs(board, word, i - 1, j, idx + 1) ||
                     dfs(board, word, i, j + 1, idx + 1) ||
                     dfs(board, word, i, j - 1, idx + 1);

        // Restore the character (backtracking)
        board[i][j] = temp;

        return found;
    }
};

int main() {
    Solution sol;
    vector<vector<char>> board = {
        {'A','B','C','E'},
        {'S','F','C','S'},
        {'A','D','E','E'}
    };
    cout << boolalpha << sol.exist(board, "ABCCED") << endl; // true
    cout << boolalpha << sol.exist(board, "SEE") << endl;    // true
    cout << boolalpha << sol.exist(board, "ABCB") << endl;   // false
}
