Brute Force.description:
Algorithm







Intuition
For every element present in the array, we will do a linear search and count the occurrence. If for any element, the occurrence is 1, we will return it.
Approach

First, we will run a loop to select the elements of the array one by one.
For every element of the array, we will perform a linear search using another loop and count its occurrence.
If for any element the occurrence is 1, we will return it.




        Code



    C++JavaPythonJavaScript12345678910111213141516171819202122232425262728293031323334353637383940#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    // Function to find the single non-repeating element using brute force
    int getSingleElement(vector<int>& arr) {
        int n = arr.size();

        // Loop through every element
        for (int i = 0; i < n; i++) {
            int num = arr[i]; // current element to check
            int cnt = 0;

            // Count occurrences of this element
            for (int j = 0; j < n; j++) {
                if (arr[j] == num)
                    cnt++;
            }

            // If it occurs only once, return it
            if (cnt == 1) return num;
        }

        // This line should never be reached
        return -1;
    }
};

int main() {
    vector<int> arr = {4, 1, 2, 1, 2};

    Solution obj;
    int ans = obj.getSingleElement(arr);

    cout << "The single element is: " << ans << endl;

    return 0;
}
