int getPriority(char C) {
    if (C == '-' || C == '+')  // Addition and subtraction have lowest precedence
        return 1;
    else if (C == '*' || C == '/')  // Multiplication and division have higher precedence
        return 2;
    else if (C == '^')  // Exponent operator has highest precedence
        return 3;
    return 0;
}

