                    result.append(stack.pop());
                }
                stack.push(c);  // Push current operator on stack
            }
        }

        // Pop all remaining elements from the stack
        while (!stack.isEmpty()) {
            result.append(stack.pop());
        }
        return result.toString();  // Return the postfix expression
    }

