    next greater elements */
    vector<int> findNGE(vector<int> &arr) {

        // Size of array
        int n = arr.size();

        // To store the answer
        vector<int> ans(n);

        // Stack 
        stack<int> st;

        // Start traversing from the back
        for(int i = n - 1; i >= 0; i--) {

            // Get the current element
            int currEle = arr[i];

            /* Pop the elements in the stack until 
            the stack is not empty and the top 
            element is not the greater element */
            while(!st.empty() && arr[st.top()] <= currEle){
                st.pop();
            }

            // Update the answer
            ans[i] = !st.empty() ? st.top() : n;

            /* Push the index of current 
            element in the stack */
            st.push(i);
        }

        // Return the answer
        return ans;
    }

    /* Function to find the indices of 
    previous smaller or equal elements */
    vector<int> findPSEE(vector<int> &arr) {

        // Size of array
        int n = arr.size();

        // To store the answer
        vector<int> ans(n);

        // Stack 
        stack<int> st;

        // Traverse on the array
        for(int i=0; i < n; i++) {

            // Get the current element
            int currEle = arr[i];

            /* Pop the elements in the stack until 
            the stack is not empty and the top 
            elements are greater than the current element */
            while(!st.empty() && arr[st.top()] > currEle){
                st.pop();
            }

            // Update the answer
            ans[i] = !st.empty() ? st.top() : -1;

            /* Push the index of current 
            element in the stack */
            st.push(i);
        }

        // Return the answer
        return ans;
    }

    /* Function to find the indices of 
    previous greater or equal elements */
    vector<int> findPGEE(vector<int> &arr) {

        // Size of array
        int n = arr.size();

        // To store the answer
        vector<int> ans(n);

        // Stack 
        stack<int> st;

        // Traverse on the array
        for(int i=0; i < n; i++) {

            // Get the current element
            int currEle = arr[i];

            /* Pop the elements in the stack until 
            the stack is not empty and the top 
            elements are smaller than the current element */
            while(!st.empty() && arr[st.top()] < currEle){
                st.pop();
            }

            // Update the answer
            ans[i] = !st.empty() ? st.top() : -1;

            /* Push the index of current 
            element in the stack */
            st.push(i);
        }

        // Return the answer
        return ans;
    }

    /* Function to find the sum of the 
    minimum value in each subarray */
    long long sumSubarrayMins(vector<int> &arr) {

        vector<int> nse = findNSE(arr);

        vector<int> psee = findPSEE(arr);

        // Size of array
        int n = arr.size();

        // To store the sum
        long long sum = 0;

        // Traverse on the array
        for(int i=0; i < n; i++) {

            // Count of first type of subarrays
            int left = i - psee[i];

            // Count of second type of subarrays
            int right = nse[i] - i;

            /* Count of subarrays where 
            current element is minimum */
            long long freq = left*right*1LL;

            // Contribution due to current element 
            long long val = (freq*arr[i]*1LL);

            // Updating the sum
            sum += val;
        }

        // Return the computed sum
        return sum;
    }

