   /* To store the frequency of least 
   frequently used data-item */
   int minFreq; 

   // To store current size of cache
   int curSize; 

public:

   // Constructor
   LFUCache(int capacity) {
       // Set the capacity
       maxSizeCache = capacity; 
       minFreq = 0; // Set minimum frequency
       curSize = 0; // Set current frequency
   }

