Brute force Approach.description:
Algorithm








We are given a string and an integer k, and we can change at most k characters to make the string contain all the same characters in any chosen window.
So the brute-force way would be to check every possible substring, and for each one, calculate how many characters we need to replace to make all characters in that substring the same.
If that number is ≤ k, we update our answer.

  Loop over each possible starting position of the substring.
  From each starting point, expand the end position one by one to form all substrings.
  Track the frequency of characters in the current substring.
  Find the most frequent character in this substring.
  Calculate how many characters need to be changed to make all characters the same.
  If the number of required changes is within the allowed limit, update the maximum length.
  Repeat this for all starting positions.







        Code



    CppJavaPythonJavascript


    1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    // Function to find the length of the longest substring 
    // that can be made with the same letter after replacing at most k characters
    int characterReplacement(string s, int k) {

        // Variable to store the maximum length of valid substring
        int maxLength = 0;

        // Traverse all possible substrings
        for (int i = 0; i < s.length(); i++) {

            // Initialize frequency array for current substring
            vector<int> freq(26, 0);

            // Track max frequency character in the current substring
            int maxFreq = 0;

            // Expand substring starting from index i
            for (int j = i; j < s.length(); j++) {

                // Update frequency of current character
                freq[s[j] - 'A']++;

                // Update the most frequent character seen so far
                maxFreq = max(maxFreq, freq[s[j] - 'A']);

                // Calculate total length of current substring
                int windowLength = j - i + 1;

                // Check how many characters we need to replace
                int replace = windowLength - maxFreq;

                // If number of replacements is within allowed k, update answer
                if (replace <= k) {
                    maxLength = max(maxLength, windowLength);
                }
            }
        }

        return maxLength;
    }
};

// Driver code
int main() {
    Solution sol;
    string s = "AABABBA";
    int k = 1;
    cout << sol.characterReplacement(s, k) << endl;
    return 0;
}
