var subarraysWithKDistinct = function(nums, k) {
    // Helper function to count subarrays with at most K distinct integers
    const atMostK = (K) => {
        let freq = new Map();
        let left = 0;
        let count = 0;

        // Traverse the array with right pointer
        for (let right = 0; right < nums.length; right++) {
            if (!freq.has(nums[right]) || freq.get(nums[right]) === 0) {
                K--;
            }

            freq.set(nums[right], (freq.get(nums[right]) || 0) + 1);

            // Shrink the window if K becomes negative
            while (K < 0) {
                freq.set(nums[left], freq.get(nums[left]) - 1);
                if (freq.get(nums[left]) === 0) {
                    K++;
                }
                left++;
            }

            count += (right - left + 1);
        }

        return count;
    };

    // Main result is difference of atMostK and atMostK-1
    return atMostK(k) - atMostK(k - 1);
};

