class Solution {
    // Function to get the Kth largest element 
    public int kthLargestElement(int[] nums, int k) {

        // Min-heap data structure
        PriorityQueue<Integer> pq = new PriorityQueue<>();

        // Add the first K elements in the Min-heap
        for(int i = 0; i < k; i++) {
