        for (int i = k + 1; i < arr.size(); i++) {
            result.add(minHeap.poll()); // remove smallest
            minHeap.add(arr.get(i));    // insert current
        }

        // Remove and add remaining elements in heap
        while (!minHeap.isEmpty()) {
            result.add(minHeap.poll());
        }

        return result;
    }
}

