Optimal Approach.description:
Algorithm








We need to assign a rank to each element of the array based on how small or large it is compared to others. The smallest number gets rank 1, the next smallest gets rank 2, and so on.
Duplicate elements should get the same rank.


 Make a copy of the array to avoid modifying the original. Sort the copied array in ascending order. Use a map or dictionary to assign rank starting from 1, skipping duplicates. Loop through the original array and replace each element with its rank using the map. 





        Code



    CppJavaPythonJavascript


    12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    // Function to replace elements by their rank in the array
    vector<int> replaceWithRank(vector<int>& arr) {
        // Copy the original array for sorting
        vector<int> sortedArr = arr;

        // Sort the array
        sort(sortedArr.begin(), sortedArr.end());

        // Create a map to store rank of each unique number
        unordered_map<int, int> rankMap;

        // Initialize rank counter
        int rank = 1;

        // Assign rank to each unique element in sorted order
        for (int num : sortedArr) {
            // If this number is not already assigned a rank
            if (rankMap.find(num) == rankMap.end()) {
                rankMap[num] = rank;
                rank++;
            }
        }

        // Replace each element in original array with its rank
        vector<int> result;
        for (int num : arr) {
            result.push_back(rankMap[num]);
        }

        return result;
    }
};

// Driver code
int main() {
    Solution obj;
    vector<int> arr = {1, 5, 8, 15, 8, 25, 9};

    vector<int> res = obj.replaceWithRank(arr);

    for (int x : res) {
        cout << x << " ";
    }

    return 0;
}
