Approach.description:
Algorithm





To determine whether a hand of cards can be rearranged into groups of size `groupSize`, we can sort the cards and always try to build a group starting from the smallest available card. We greedily check if the next `groupSize - 1` consecutive cards exist and reduce their count. A `TreeMap` (in C++ or Java) or a sorted map can help maintain keys in sorted order while efficiently accessing and updating the card counts.



  Check if total number of cards is divisible by groupSize; if not, return false.
  Store the frequency of each card in a sorted data structure.
  Iterate over the sorted keys (card values) from smallest to largest.
  For each key, try to form a group of groupSize starting from that key.
  If there are not enough cards to build a group, return false.
  Decrement the counts for each card used in the group.
  If all groups are successfully formed, return true.


1/3









        Code



    C++JavaPythonJavaScript1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859606162636465666768697071#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    bool isNStraightHand(vector<int>& hand, int groupSize) {
        // If total cards can't be divided evenly, return false
        if (hand.size() % groupSize != 0) return false;

        // Store the frequency of each card
        map<int, int> freq;
        for (int card : hand) {
            freq[card]++;
        }

        // Create an iterator pointing to the beginning of the frequency map
        auto it = freq.begin();

        // Loop through all keys in the map
        while (it != freq.end()) {

            // Skip cards that are already used up
            if (it->second == 0) {
                ++it;
                continue;
            }

            // Store the starting card of the group
            int start = it->first;

            // Number of times we need to form this group
            int count = it->second;

            // Try to form a group of consecutive cards of size groupSize
            for (int i = 0; i < groupSize; ++i) {

                // If the current required card is missing or doesn't have enough frequency
                if (freq[start + i] < count) return false;

                // Decrease the frequency for current card
                freq[start + i] -= count;
            }

            // Move the iterator to the next element
            ++it;
        }

        // All groups formed successfully
        return true;
    }
};

// Driver code
int main() {
    Solution sol;

    // Test case 1
    vector<int> hand1 = {1,2,3,6,2,3,4,7,8};
    int groupSize1 = 3;
    cout << sol.isNStraightHand(hand1, groupSize1) << endl;  
    // Output: 1 (true)

    // Test case 2
    vector<int> hand2 = {1,2,3,4,5};
    int groupSize2 = 4;
    cout << sol.isNStraightHand(hand2, groupSize2) << endl; 
    // Output: 0 (false)

    return 0;
}
