                if (!freq.containsKey(card) || freq.get(card) < count) return false;

                // Decrease the frequency
                if (freq.get(card) == count) freq.remove(card);
                else freq.put(card, freq.get(card) - count);
            }
        }

        // All groups formed successfully
        return true;
    }
}

