Brute force Approach.description:
Algorithm 









  The objective is to ensure that each child receives at least one candy. Additionally, any child with a higher rating than their adjacent neighbor must receive strictly more candies than that neighbor.  
  The brute force approach simulates this behavior by performing repeated traversals from both directions, adjusting the candy distribution to maintain the constraints.

  Initialize an array to track candies for each child and assign 1 candy to each child (minimum required).
  Iterate repeatedly until no updates are needed in a complete traversal
  Traverse from left to right:

    For each child, if their rating is greater than the previous child’s and their current candy count is not greater, update it to one more than the previous child's candy count.

  Traverse from right to left:

    For each child, if their rating is greater than the next child’s and their current candy count is not greater, update it to one more than the next child's candy count.

  Continue alternating left-to-right and right-to-left traversals until no modifications occur in a full pass.
  Return the total number of candies by summing up the final values in the array.



                    Dry Run:




        Code



    CppJavaPythonJavascript


    12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    // Function to calculate the minimum number of candies 
    int candy(vector<int>& ratings) {
        // Total number of children
        int n = ratings.size();

        // Array to keep track of candies given to each child, initialized to 1
        vector<int> candies(n, 1);

        // Boolean flag to track if we made any change in the current iteration
        bool updated = true;

        // Repeat until no changes are made in a full scan
        while (updated) {
            updated = false;

            // Left to right pass to check increasing rating condition
            for (int i = 1; i < n; ++i) {
                if (ratings[i] > ratings[i - 1] && candies[i] <= candies[i - 1]) {
                    candies[i] = candies[i - 1] + 1;
                    updated = true;
                }
            }

            // Right to left pass to check decreasing rating condition
            for (int i = n - 2; i >= 0; --i) {
                if (ratings[i] > ratings[i + 1] && candies[i] <= candies[i + 1]) {
                    candies[i] = candies[i + 1] + 1;
                    updated = true;
                }
            }
        }

        // Return the total candies by summing the array
        return accumulate(candies.begin(), candies.end(), 0);
    }
};

// Driver code
int main() {
    Solution obj;
    vector<int> ratings = {1, 0, 5};
    cout << "Minimum candies required: " << obj.candy(ratings) << endl;
    return 0;
}
