Brute force Approach.description:
Algorithm








We try all possible combinations by removing one interval at a time and check if the remaining intervals are non-overlapping.In brute force, we consider every subset of intervals and check if it's valid (non-overlapping). Then we keep track of the max size of such valid subset. answer = total intervals - max valid subset size.
 Generate all subsets of the given intervals. For each subset, check if the intervals are non-overlapping by sorting and comparing end times. Track the size of the largest valid subset (non-overlapping). Return total intervals - size of max valid subset. 




        Code



    CppJavaPythonJavascript


    123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
     // Function to find the minimum number of intervals to remove to make all intervals non-overlapping
    int eraseOverlapIntervals(vector<vector<int>>& intervals) {

        // Total number of intervals
        int n = intervals.size();

        // Store the max size of non-overlapping subset
        int maxValid = 0;

        // Try all subsets using bitmasking
        for (int mask = 0; mask < (1 << n); ++mask) {

            // Vector to hold selected subset
            vector<vector<int>> subset;

            // Construct subset from bitmask
            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i))
                    subset.push_back(intervals[i]);
            }

            // Sort subset by start time
            sort(subset.begin(), subset.end());

            // Check if it's non-overlapping
            bool valid = true;
            for (int i = 1; i < subset.size(); ++i) {
                if (subset[i][0] < subset[i-1][1]) {
                    valid = false;
                    break;
                }
            }

            // If valid, update maxValid size
            if (valid)
                maxValid = max(maxValid, (int)subset.size());
        }

        // Answer = total - size of max valid subset
        return n - maxValid;
    }
};
// Driver Code
