Approach.description:
Algorithm







    A connected component is a group of vertices in which every vertex can be reached from any other vertex in the same group.
    To count the number of connected components, we need to explore the graph so that each vertex is visited exactly once and grouped into its component.
    We can do this using either DFS or BFS. Each time we start a new search from an unvisited vertex, we discover a new component and mark all vertices in that component as visited.
    This ensures that we don’t count the same component more than once.

        Use a visited array to track the vertices that has been visited once.
        Build an adjacency list from the given edges for efficient traversal.
        For each vertex:

                If the vertex is not visited, perform DFS/BFS starting from it.
                This traversal will mark all vertices in the same component as visited.
                Increment the number of components for every traversal.


        Once all the vertices are visited, return the number of connected components.






        Code



    CppJavaPythonJavascript


    1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859606162636465666768697071#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    // Function to count connected components in an undirected graph
    int countComponents(int V, vector<vector<int>>& edges) {

        // Create adjacency list from edge list
        vector<vector<int>> adj(V);
        for (auto &e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }

        // Vector to keep track of visited nodes
        vector<int> visited(V, 0);

        // Variable to count the number of connected components
        int components = 0;

        // Traverse all nodes in the graph
        for (int i = 0; i < V; ++i) {

            // If the node is not visited, it's a new component
            if (!visited[i]) {
                components++;

                // Start BFS from this node
                queue<int> q;
                q.push(i);
                visited[i] = 1;

                // Perform BFS traversal
                while (!q.empty()) {
                    int node = q.front();
                    q.pop();

                    // Visit all unvisited neighbors
                    for (auto &nbr : adj[node]) {
                        if (!visited[nbr]) {
                            visited[nbr] = 1;
                            q.push(nbr);
                        }
                    }
                }
            }
        }

        // Return the total number of connected components
        return components;
    }
};

int main() {
    // Number of vertices
    int V = 5;

    // List of undirected edges
    vector<vector<int>> edges = {{0,1},{1,2},{3,4}};

    // Create solution object
    Solution sol;

    // Print the number of connected components
    cout << "Number of Connected Components: " 
         << sol.countComponents(V, edges) << endl;

    return 0;
}
