            # Remove used words when moving to the next BFS level
            if len(path) > level:
                level += 1
                for word in used_on_level:
                    word_set.discard(word)

            word = path[-1]

            # If we found the target word
            if word == endWord:
                if not ans:
                    ans.append(path[:])
                elif len(ans[0]) == len(path):
                    ans.append(path[:])

