// Class to manage Disjoint Set Union
class DSU {
public:
    vector<int> parent, rank;

    // Initialize DSU with n nodes
    DSU(int n) {
        parent.resize(n);
        rank.resize(n, 0);

        // Initially, every node is its own parent
        for(int i = 0; i < n; i++) {
            parent[i] = i;
        }
    }

    // Find with path compression
    int find(int x) {
        if(parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }

    // Union by rank
    void unite(int x, int y) {
        int px = find(x);
        int py = find(y);

        if(px == py) return;

        if(rank[px] < rank[py])
            parent[px] = py;
        else if(rank[px] > rank[py])
            parent[py] = px;
        else {
            parent[py] = px;
            rank[px]++;
        }
    }
};

