    private void dfs3(int node, int[] vis, List<Integer>[] adjT) {
        vis[node] = 1;
        for (int it : adjT[node]) {
            if (vis[it] == 0) {
                dfs3(it, vis, adjT);
            }
        }
    }

    // Function to find number of strongly connected components
    public int kosaraju(int V, List<Integer>[] adj) {
