        Stack<Integer> st = new Stack<>();

        // Step 1: Do DFS to fill stack
        for (int i = 0; i < V; i++) {
            if (vis[i] == 0) {
                dfs(i, vis, adj, st);
            }
        }

        // Step 2: Build transpose graph
        List<Integer>[] adjT = new ArrayList[V];
        for (int i = 0; i < V; i++) {
            adjT[i] = new ArrayList<>();
        }
        Arrays.fill(vis, 0);

        for (int i = 0; i < V; i++) {
            for (int it : adj[i]) {
                adjT[it].add(i);
            }
        }

