Tabulation Approach.description:
Algorithm




                        Instead of solving the problem recursively, we can build the solution iteratively. Each
                            stone's minimum cost depends only on the previous one or two stones. By filling a DP array
                            step by step, we avoid recursion overhead and directly compute the answer.

                        Approach:

                            Initialize a DP array of size n, where dp[i] represents the
                                minimum cost to reach stone i.
                            Set dp[0] = 0 (no cost to start).
                            Iterate from 1 to n-1:

                                    Jump One: From i-1 to i.
                                    Jump Two: From i-2 to i (only if
                                        i > 1).



                            At each step, store the minimum of the two jumps in dp[i].
                            The final answer is dp[n-1], the minimum cost to reach the last stone.





                        Code








                    C++JavaPythonJavaScript



                                1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253

                            #include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    // Computes minimum energy to reach last index using bottom-up DP
    int frogJump(const vector<int>& height) {
        // Handle empty input
        if (height.empty()) return 0;

        // Fetch size of the input
        int n = (int)height.size();

        // Create dp array where dp[i] = min energy to reach i
        vector<int> dp(n, INT_MAX);

        // Base case: cost to stand on first stone is zero
        dp[0] = 0;

        // Iterate over stones from index 1 to n-1
        for (int ind = 1; ind < n; ind++) {
            // Compute cost for a jump from ind-1
            int jumpOne = dp[ind - 1] + abs(height[ind] - height[ind - 1]);

            // Initialize jumpTwo with large value
            int jumpTwo = INT_MAX;

            // If possible, compute cost for a jump from ind-2
            if (ind > 1) {
                jumpTwo = dp[ind - 2] + abs(height[ind] - height[ind - 2]);
            }

            // Take the minimum of the two options
            dp[ind] = min(jumpOne, jumpTwo);
        }

        // Return min energy to reach last stone
        return dp[n - 1];
    }
};

int main() {
    // Define the heights array
    vector<int> height{30, 10, 60, 10, 60, 50};

    // Create Solution instance
    Solution sol;

    // Compute and print the minimum energy
    cout << sol.frogJump(height) << endl; // Expected: 40
    return 0;
}




