Tabulation Approach.description:
Algorithm





                            In this variation of the classic frog jump problem, the frog can jump from any stone to one
                            of the previous k stones. The cost of each jump is the absolute difference in
                            height between the stones. The goal is to minimize the total cost to reach the last stone
                            starting from the first.


                            Instead of using recursion with memoization, we can solve this iteratively using bottom-up
                            dynamic programming. This helps avoid recursion stack overhead and provides an efficient way
                            to build the solution from the base case.




                            We use a dp[] array where dp[i] represents the minimum cost to
                            reach the ith stone.

                            We initialize dp[0] = 0 because the frog starts there with no cost.
                            For every stone from index 1 to n-1, we try all possible jump
                                lengths j from 1 to k.
                            For every valid jump, we compute the cost as
                                dp[i - j] + abs(height[i] - height[i - j]).

                            We take the minimum of all such possible jump costs and store it in dp[i].

                            Finally, dp[n - 1] contains the minimum cost to reach the last stone.







                        Code






                        CppJavaPythonJavascript








                                12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152

                            #include <bits/stdc++.h>
using namespace std;

// Function to compute the minimum cost to reach the end using at most 'k' jumps
int solveUtil(int n, vector<int>& height, vector<int>& dp, int k) {
    // Base case: cost to reach the first stone is 0
    dp[0] = 0;

    // Iterate over each stone
    for (int i = 1; i < n; i++) {
        // Initialize the minimum cost for this stone as large value
        int mmSteps = INT_MAX;

        // Try all possible jump lengths from 1 to k
        for (int j = 1; j <= k; j++) {
            // Ensure jump doesn't go out of bounds
            if (i - j >= 0) {
                // Cost of jumping from (i - j) to i
                int jump = dp[i - j] + abs(height[i] - height[i - j]);
                // Keep track of the minimum cost
                mmSteps = min(mmSteps, jump);
            }
        }

        // Store the computed minimum cost for this stone
        dp[i] = mmSteps;
    }

    // The last element of dp stores the answer
    return dp[n - 1];
}

// Main function to solve the problem
int solve(int n, vector<int>& height, int k) {
    // Initialize DP array with -1
    vector<int> dp(n, -1);
    // Fill DP array iteratively
    return solveUtil(n, height, dp, k);
}

// Driver code
int main() {
    // Heights of stones
    vector<int> height{30, 10, 60, 10, 60, 50};
    int n = height.size();
    int k = 2;

    // Output result
    cout << solve(n, height, k) << endl;
    return 0;
}




