                /* Initialize variables to store the number
                of ways from the cell above (up) and left (left)*/
                let up = (i > 0) ? prev[j] : 0;
                let left = (j > 0) ? temp[j - 1] : 0;

                /* Calculate the number of ways to reach
                the current cell by adding 'up' and 'left'*/
                temp[j] = up + left;
