        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {

                // Base conditions
                if (matrix[i][j] == 1) {
                    /* If there's an obstacle at the 
                    cell, no paths can pass through it*/
                    dp[i][j] = 0;
                    continue;
