                    if (j > 0)
                        left += temp[j - 1];
                    else
                        left += (int)1e9;

                    // Take minimum of both directions
                    temp[j] = Math.min(up, left);
                }
            }

            // Move current row to previous
            prev = temp;
        }

        // Return result at destination
        return prev[m - 1];
    }
}

