Space Optimization Approach.description:
Algorithm







                    If we closely look the relation,
dp[i][j] = matrix[i][j] + min(dp[i+1][j] + dp[i+1][j+1]))
We see that we only need the next row, in order to calculate dp[i][j]. Therefore we can space optimize it.
Initially we can take a dummy row (say front). We initialize this row to the triangle matrix's last row (as done in tabulation).
Now the current row (say cur) only needs the front row’s value in order to calculate dp[i][j].


At last, front [0] will give us the required answer.



        Code



    CppJavaPythonJavascript


    1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859606162636465666768#include <bits/stdc++.h>
using namespace std;

// Define a class to hold the solution
class Solution {
public:
    // Function to calculate the minimum path sum in triangle
    int minimumPathSum(vector<vector<int>> &triangle, int n) {

        // Create an array to store the values of the row below
        vector<int> front(n, 0);

        // Create an array to store the values of the current row
        vector<int> cur(n, 0);

        // Initialize front with values from the last row of the triangle
        for (int j = 0; j < n; j++) {
            front[j] = triangle[n - 1][j];
        }

        // Traverse the triangle from bottom to top
        for (int i = n - 2; i >= 0; i--) {

            // Traverse each element in the current row
            for (int j = i; j >= 0; j--) {

                // Calculate sum when going down
                int down = triangle[i][j] + front[j];

                // Calculate sum when going diagonal
                int diagonal = triangle[i][j] + front[j + 1];

                // Store the minimum of the two in current row
                cur[j] = min(down, diagonal);
            }

            // Move current row values to front for next iteration
            front = cur;
        }

        // Return the final answer from the top of triangle
        return front[0];
    }
};

// Main function to test the solution
int main() {

    // Create the triangle
    vector<vector<int>> triangle{
