// Class to solve Ninja and his friends using memoization
class Solution {
    // Recursive function with memoization
    solve(i, j1, j2, n, m, grid, dp) {
        // Out of boundary check
        if (j1 < 0 || j1 >= m || j2 < 0 || j2 >= m)
            return -1e9;

        // Base case: last row
        if (i === n - 1) {
            if (j1 === j2) return grid[i][j1];
            else return grid[i][j1] + grid[i][j2];
        }

        // If already computed return it
        if (dp[i][j1][j2] !== -1) return dp[i][j1][j2];

        // Take chocolates from current cell(s)
        let curr = (j1 === j2) ? grid[i][j1] : grid[i][j1] + grid[i][j2];
        let maxi = -1e9;

        // Try all 9 moves
        for (let dj1 = -1; dj1 <= 1; dj1++) {
            for (let dj2 = -1; dj2 <= 1; dj2++) {
                let ans = curr + this.solve(i + 1, j1 + dj1, j2 + dj2,
                                            n, m, grid, dp);
                maxi = Math.max(maxi, ans);
            }
        }
        // Store result
        dp[i][j1][j2] = maxi;
        return maxi;
    }

    // Main function to call
    maximumChocolates(n, m, grid) {
        let dp = Array.from({ length: n }, () =>
                  Array.from({ length: m }, () =>
                  Array(m).fill(-1)));
        return this.solve(0, 0, m - 1, n, m, grid, dp);
    }
}

