Memoization Approach.description:
Algorithm





                            This is a Coin Change II problem where we want to count the total number of
                            ways
                            to make a target sum using an unlimited supply of given coins.
                            For every coin, we have two choices:
                            either take it (and stay at the same index since coins are unlimited),
                            or not take it (and move to the previous index).
                            By exploring these choices recursively and storing results using DP,
                            we can efficiently solve the problem.

                        Approach

                            Define a recursive function countWaysToMakeChangeUtil(ind, T) which returns
                                the number of ways to form sum T using coins up to index ind.

                            Base case: If ind == 0, we can only form T if
                                it is divisible by the first coin.
                            At each step:

                                    Not Taken: move to the previous index.
                                    Taken: stay at the same index and reduce T by the
                                        current coin’s value.


                            Use a DP table dp[ind][T] to store results and avoid recomputation.
                            The final answer is countWaysToMakeChange(n-1, target).





                        Code






                        CppJavaPythonJavascript








                                1234567891011121314151617181920212223242526272829303132333435363738394041

                            #include <bits/stdc++.h>
using namespace std;

// Recursive function with memoization to count ways to make change
long countWaysToMakeChangeUtil(vector<int>& arr, int ind, int T, vector<vector<long>>& dp) {
    // Base case: if we are at the first element
    if (ind == 0) {
        return (T % arr[0] == 0); // Only one way if divisible
    }

    // If already calculated, return stored value
    if (dp[ind][T] != -1)
        return dp[ind][T];

    // Do not take the current coin
    long notTaken = countWaysToMakeChangeUtil(arr, ind - 1, T, dp);

    // Take the current coin (if feasible)
    long taken = 0;
    if (arr[ind] <= T)
        taken = countWaysToMakeChangeUtil(arr, ind, T - arr[ind], dp);

    // Store the result in DP table
    return dp[ind][T] = notTaken + taken;
}

// Function to initialize DP table and start recursion
long countWaysToMakeChange(vector<int>& arr, int n, int T) {
    vector<vector<long>> dp(n, vector<long>(T + 1, -1));
    return countWaysToMakeChangeUtil(arr, n - 1, T, dp);
}

int main() {
    vector<int> arr = {1, 2, 3};
    int target = 4;
    int n = arr.size();

    cout << "The total number of ways is " << countWaysToMakeChange(arr, n, target) << endl;
    return 0;
}




