Tabulation Approach.description:
Algorithm



                        To convert the memoization approach to a tabulation one, create a dp array with the same size
                            as done in memoization. We can initialize it as 0.
                        First, we need to initialize the base conditions of the recursive solution.

                            At ind==0, we are considering the first element, if the target value is divisible by the
                                first coin’s value, we set the cell's value as 1 or else 0.
                            Next, we are done for the first row, so our ‘ind’ variable will move from 1 to n-1,
                                whereas our ‘target’ variable will move from 0 to ‘T’. We will set the nested loops to
                                traverse the dp array.
                            Inside the nested loops, we will apply the recursive logic to find the answer of the
                                cell.
                            When the nested loop execution has ended, we will return dp[n-1][T] as our answer.





                        Code






                        CppJavaPythonJavascript








                                12345678910111213141516171819202122232425262728293031323334353637383940

                            #include <bits/stdc++.h>
using namespace std;

// Function to count the number of ways to make change for a given target sum
long countWaysToMakeChange(vector<int>& arr, int n, int T) {
    vector<vector<long>> dp(n, vector<long>(T + 1, 0)); // Create a DP table

    // Initializing base condition
    for (int i = 0; i <= T; i++) {
        if (i % arr[0] == 0)
            dp[0][i] = 1;
        // Else condition is automatically fulfilled,
        // as dp array is initialized to zero
    }

    for (int ind = 1; ind < n; ind++) {
        for (int target = 0; target <= T; target++) {
            long notTaken = dp[ind - 1][target];

            long taken = 0;
            if (arr[ind] <= target)
                taken = dp[ind][target - arr[ind]];

            dp[ind][target] = notTaken + taken;
        }
    }

    return dp[n - 1][T];
}

int main() {
    vector<int> arr = {1, 2, 3};
    int target = 4;
    int n = arr.size();

    cout << "The total number of ways is " << countWaysToMakeChange(arr, n, target) << endl;

    return 0; // Return 0 to indicate successful program execution
}




