    int rodCutting(vector<int>& price, int n) {
        // Initialize DP table with dimensions [n][n + 1]
        vector<vector<int>> dp(n, vector<int>(n + 1, 0));

        for(int length = 0; length <= n; length++){
            dp[0][length] = price[0]*length;
        }

        // Fill the DP table
        for (int ind = 1; ind < n; ++ind) { 
