Space Optimized Approach.description:
Algorithm







                        If we look closely, we are essentially using only two rows in our DP table: dp[ind-1][ ] and dp[ind][ ]. This means we don’t need to maintain the entire 2D array. Instead, we can optimize space by using two 1D arrays — prev and cur, where prev represents dp[ind-1] and cur represents dp[ind].

We can simply replace all instances of dp[ind-1] with prev, and dp[ind] with cur. After completing each inner iteration, we can update prev = cur so that the current row becomes the previous row for the next step.



        Code



    CppJavaPythonJavascript


    123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960#include <bits/stdc++.h>
using namespace std;

class Solution {

public:

    // Function to compute LCS using 2-row DP
    int lcs(string s1, string s2) {

        // Get sizes
        int n = s1.size();
        int m = s2.size();

        // Initialize prev and cur rows
        vector<int> prev(m + 1, 0), cur(m + 1, 0);

        // Fill rows
        for (int ind1 = 1; ind1 <= n; ind1++) {
            for (int ind2 = 1; ind2 <= m; ind2++) {

                // If characters match
                if (s1[ind1 - 1] == s2[ind2 - 1])
                    cur[ind2] = 1 + prev[ind2 - 1];

                // Else take max from prev row or left
                else
                    cur[ind2] = max(prev[ind2], cur[ind2 - 1]);
            }

            // Move cur to prev
            prev = cur;
        }

        // Return result
        return prev[m];
    }

    // Function to compute LPS
    int longestPalindromeSubsequence(string s) {
        string t = s;
        reverse(t.begin(), t.end());
        return lcs(s, t);
    }

    // Function to compute min insertions
    int minInsertion(string s) {
        int n = s.size();
        int k = longestPalindromeSubsequence(s);
        return n - k;
    }
};

int main() {
    Solution sol;
    string s = "abcaa";
    cout << "The Minimum insertions required to make string palindrome: "
         << sol.minInsertion(s) << endl;
    return 0;
