Space Optimized Approach.description:
Algorithm







                        If we look closely, we are essentially using only two rows in our DP table: dp[ind-1][ ] and dp[ind][ ]. This means we don’t need to maintain the entire 2D array. Instead, we can optimize space by using two 1D arrays — prev and cur, where prev represents dp[ind-1] and cur represents dp[ind].

We can simply replace all instances of dp[ind-1] with prev, and dp[ind] with cur. After completing each inner iteration, we can update prev = cur so that the current row becomes the previous row for the next step.



        Code



    CppJavaPythonJavascript


    1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253#include <bits/stdc++.h>
using namespace std;

// Class containing the solution
class Solution {
public:
    // Function to calculate minimum operations
    int minOperations(string s1, string s2) {
        // Get the lengths of both strings
        int n = s1.size(), m = s2.size();

        // Create two 1D DP arrays
        vector<int> prev(m + 1, 0), cur(m + 1, 0);

        // Iterate through each character of s1
        for (int i = 1; i <= n; i++) {

            // Iterate through each character of s2
            for (int j = 1; j <= m; j++) {

                // If characters match, increment LCS length
                if (s1[i - 1] == s2[j - 1])
                    cur[j] = 1 + prev[j - 1];

                // Else, take max from left or top
                else
                    cur[j] = max(prev[j], cur[j - 1]);
            }

            // Update prev row to current
            prev = cur;
        }

        // Calculate total operations
        int lcs = prev[m];
        return (n - lcs) + (m - lcs);
    }
};

// Main function
int main() {
    // Input strings
    string s1 = "heap", s2 = "pea";

    // Create object of Solution
    Solution obj;

    // Call function and print result
    cout << obj.minOperations(s1, s2) << endl;

    return 0;
}
