    wildcardMatchingUtil(S1, S2, i, j, dp) {
        // Base Case 1: Both pattern and text matched
        if (i < 0 && j < 0) return true;

        // Base Case 2: Pattern exhausted but text remains
        if (i < 0 && j >= 0) return false;

        // Base Case 3: Text exhausted but pattern may have '*'
        if (j < 0 && i >= 0) return this.isAllStars(S1, i);

        // If already computed, return stored value
        if (dp[i][j] !== -1) return dp[i][j] === 1;

        // If characters match or pattern has '?'
        if (S1[i] === S2[j] || S1[i] === '?') {
            dp[i][j] = this.wildcardMatchingUtil(S1, S2, i - 1, j - 1, dp) ? 1 : 0;
        }
        // If pattern has '*', try both options
        else if (S1[i] === '*') {
            dp[i][j] = (this.wildcardMatchingUtil(S1, S2, i - 1, j, dp) ||
                        this.wildcardMatchingUtil(S1, S2, i, j - 1, dp)) ? 1 : 0;
