Memoization Approach.description:
Algorithm









Intuition
Every day, we can either skip trading or buy/sell a stock based on whether we are holding one and how many trades are left. To find the maximum profit, we try all possible choices using recursion.


  Think in terms of three things: the current day, whether we can buy or need to sell, and how many trades are left.
  If we can buy: either skip or buy the stock.
  If we need to sell: either skip or sell the stock (which completes one trade).
  Return the maximum profit from these options.


Base Cases

  If all days are finished → profit is 0.
  If no trades are left → profit is 0.


Memoization

  Use a table to store answers for each combination of day, buy/sell state, and remaining trades.
  If a value is already calculated, use it instead of recalculating.







Code












C++JavaPythonJavaScript



#include <bits/stdc++.h>
using namespace std;
class StockProfit{
int getAns(vector<int>& Arr, int n, int ind, int buy, int cap, vector<vector<vector<int>>>& dp) {
    // Base case: If we reach the end of the array or run out of allowed transactions, return 0.
    if (ind == n || cap == 0)
        return 0;

    // If the result is already calculated, return it.
    if (dp[ind][buy][cap] != -1)
        return dp[ind][buy][cap];

    int profit;

    if (buy == 0) { // We can buy the stock
        profit = max(0 + getAns(Arr, n, ind + 1, 0, cap, dp),
                     -Arr[ind] + getAns(Arr, n, ind + 1, 1, cap, dp));
    }

    if (buy == 1) { // We can sell the stock
        profit = max(0 + getAns(Arr, n, ind + 1, 1, cap, dp),
                     Arr[ind] + getAns(Arr, n, ind + 1, 0, cap - 1, dp));
    }

    // Store and return the calculated profit.
    return dp[ind][buy][cap] = profit;
}

int maxProfit(vector<int>& prices, int n) {
    // Creating a 3D DP array of size [n][2][3]
    vector<vector<vector<int>>> dp(n, vector<vector<int>>(2, vector<int>(3, -1)));

    // Call the recursive function to calculate maximum profit
    return getAns(prices, n, 0, 0, 2, dp);
}

int main() {
    vector<int> prices = {3, 3, 5, 0, 0, 3, 1, 4};
    int n = prices.size();

    // Call the maxProfit function and print the result
    cout << "The maximum profit that can be generated is " << maxProfit(prices, n);

    return 0;
}






