Space Optimization Approach.description:
Algorithm









Space Optimization
We only need the values from the next day to calculate the current day’s values, so we don’t need to keep the entire 3D table.


Keep one table (ahead) to store the next day’s values and fill it with 0 initially.
Use another table (cur) to calculate the current day’s values.
For each day, calculate all values using ahead and store them in cur.
After finishing the day, copy cur into ahead for the next calculation.
The final answer is the value in ahead for the first day with two trades left.





        Code



    C++JavaPythonJavaScript1234567891011121314151617181920212223242526272829303132333435363738#include <bits/stdc++.h>
using namespace std;
class StockProfit{
int maxProfit(vector<int>& Arr, int n) {
    // Create two 2D arrays to store the profit information, one for the current state and one for the ahead state.
    vector<vector<int>> ahead(2, vector<int>(3, 0));
    vector<vector<int>> cur(2, vector<int>(3, 0));

    for (int ind = n - 1; ind >= 0; ind--) {
        for (int buy = 0; buy <= 1; buy++) {
            for (int cap = 1; cap <= 2; cap++) {
                if (buy == 0) { // We can buy the stock
                    cur[buy][cap] = max(0 + ahead[0][cap], 
                                        -Arr[ind] + ahead[1][cap]);
                }

                if (buy == 1) { // We can sell the stock
                    cur[buy][cap] = max(0 + ahead[1][cap],
                                        Arr[ind] + ahead[0][cap - 1]);
                }
            }
        }
        // Update the ahead state with the current state for the next iteration.
        ahead = cur;
    }

    return ahead[0][2];
}

int main() {
    vector<int> prices = {3, 3, 5, 0, 0, 3, 1, 4};
    int n = prices.size();

    // Call the maxProfit function and print the result
    cout << "The maximum profit that can be generated is " << maxProfit(prices, n);

    return 0;
