class Solution{
function getAns(Arr, ind, buy, n, dp) {
    // Base case: if the index is greater than or equal to n, return 0
    if (ind >= n) return 0;

    // Check if the result is already computed and stored in dp
    if (dp[ind][buy] !== -1) return dp[ind][buy];

    let profit;

    if (buy === 0) { // We can buy the stock
        profit = Math.max(
            0 + getAns(Arr, ind + 1, 0, n, dp),
            -Arr[ind] + getAns(Arr, ind + 1, 1, n, dp)
        );
    }

    if (buy === 1) { // We can sell the stock
        profit = Math.max(
            0 + getAns(Arr, ind + 1, 1, n, dp),
            Arr[ind] + getAns(Arr, ind + 2, 0, n, dp)
        );
    }

    // Store the result in dp and return it
    dp[ind][buy] = profit;
    return profit;
}

function stockProfit(Arr) {
    const n = Arr.length;
    // Create a 2D dp array filled with -1 to store computed results
    const dp = new Array(n).fill().map(() => new Array(2).fill(-1));

    // Call the recursive function to compute the maximum profit
    const ans = getAns(Arr, 0, 0, n, dp);
    return ans;
}

