        List<Integer> lisSeq = new ArrayList<>();
        int curr = maxIndex;
        while (curr != -1) {
            lisSeq.add(nums[curr]);
            curr = prev[curr];
        }

        // Reverse sequence as it was built backwards
        Collections.reverse(lisSeq);

        return lisSeq;
    }
}

