            else if (exp.charAt(ind) == '|') {  // OR operator
                if (isTrue == 1) ways = (ways + (lF * rT) + (lT * rF) + (lT * rT)) % 1000000007;
                else ways = (ways + (lF * rF)) % 1000000007;
            }
            else {  // XOR operator
                if (isTrue == 1) ways = (ways + (lF * rT) + (lT * rF)) % 1000000007;
                else ways = (ways + (lF * rF) + (lT * rT)) % 1000000007;
            }
        }

        dp[i][j][isTrue] = ways;
        return (int) ways;
    }

    // Function to start evaluating the expression
    public static int evaluateExp(String exp) {
        int n = exp.length();
        long[][][] dp = new long[n][n][2];  // DP table initialization
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < 2; k++) {
                    dp[i][j][k] = -1;
                }
            }
        }
        return (int) f(0, n - 1, 1, exp, dp);  // Start evaluation with isTrue set to true.
    }

    public static void main(String[] args) {
        String exp = "F|T^F";  // Example expression

        // Evaluate the expression and find the number of ways to get the result as True
        int ways = evaluateExp(exp);

        // Output the result
        System.out.println("The total number of ways: " + ways);
    }
}

