// Solution class with both functions
class Solution {

    // Function to compute largest rectangle in histogram
    largestRectangleArea(heights) {

        // Add a sentinel bar
        heights.push(0);

        // Stack for indices
        const stack = [];
        let maxArea = 0;

        // Traverse histogram
        for (let i = 0; i < heights.length; i++) {

            // Pop and calculate area
            while (stack.length && heights[i] < heights[stack[stack.length - 1]]) {
                const height = heights[stack.pop()];
                const width = stack.length === 0 ? i : i - stack[stack.length - 1] - 1;
                maxArea = Math.max(maxArea, height * width);
            }

            // Push current index
            stack.push(i);
        }

        return maxArea;
    }

    // Function to compute maximal rectangle in binary matrix
    maximalRectangle(matrix) {

        // Return 0 for empty matrix
        if (matrix.length === 0) return 0;

        const m = matrix[0].length;
        const height = new Array(m).fill(0);
        let maxArea = 0;

        // Traverse each row
        for (let row of matrix) {

            // Update histogram
            for (let i = 0; i < m; i++) {
                if (row[i] === '1') height[i]++;
                else height[i] = 0;
            }

            // Update max area
            maxArea = Math.max(maxArea, this.largestRectangleArea([...height]));
        }

        return maxArea;
    }
}

