    void insert(int num) {
        // Start from root
        Node* node = root;

        // Traverse bits from MSB (31) to LSB (0)
        for (int i = 31; i >= 0; i--) {
            // Extract the current bit
            int bit = (num >> i) & 1;

            // If path for this bit doesn't exist, create it
            if (!node->containsKey(bit)) {
                node->put(bit, new Node());
            }

            // Move to the next node
            node = node->get(bit);
        }
    }

