Approach.description:
Algorithm







                        We are generating each term in a sequence by describing the previous term. For example, if the previous term is 1211, we say it as "one 1, one 2, two 1s", giving 111221.

                            Start from the first term as "1".
                            For each new term, scan the previous term from left to right and count how many times the current digit appears consecutively.
                            Append the count followed by the digit to build the next term.
                            Repeat this process until reaching the required term.






        Code



    CppJavaPythonJavascript


    123456789101112131415161718192021222324252627282930313233343536373839404142434445#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    // Function to generate the nth term of the count-and-say sequence
    string countAndSay(int n) {
        string result = "1";

        // Generate the sequence up to the nth term
        for (int i = 1; i < n; ++i) {
            string current = "";
            int count = 1;

            // Traverse the previous result
            for (int j = 1; j < result.size(); ++j) {
                // If current character matches previous, increment count
                if (result[j] == result[j - 1]) {
                    count++;
                } else {
                    // Append count and character to current result
                    current += to_string(count) + result[j - 1];
                    count = 1;
                }
            }

            // Append the last group
            current += to_string(count) + result.back();

            // Update result for next iteration
            result = current;
        }

        // Return the final result
        return result;
    }
};

int main() {
    Solution solver;
    int n = 5;
    cout << "Count and Say term " << n << ": " << solver.countAndSay(n) << endl;
    return 0;
}
